import os
import torch
from transformers import Qwen2_5_VLForConditionalGeneration, Qwen2_5_VLProcessor

# ================= Path Configuration =================
# Path to the original base model or architecture configuration
base_model_path = "/home/zxn/MomaGraph-R1" 
# Path to the raw SFT weights (usually generated by custom trainers like Easy-R1)
sft_bin_path = "/data/colosseum_dataset/checkpoints/sft/v1/checkpoint-epoch-1/pytorch_model.bin"
# Target directory for the converted standard Hugging Face format
save_path = "/data/colosseum_dataset/checkpoints/sft/v1/checkpoint-epoch-1-hf" 

def _remap_key(k): 
    """
    Remaps internal state_dict keys from custom trainer formats 
    to the standard Hugging Face transformers class structure.
    """
    # Map language model head
    if "lm_head" in k: return "lm_head.weight" if "weight" in k else "lm_head.bias"
    # Map visual encoder components
    if "visual." in k: return "model.visual." + k.split("visual.", 1)[1]
    # Map language model backbone (layers, embeddings, and norms)
    for keyword in ["layers.", "embed_tokens.", "norm."]:
        if keyword in k: return "model.language_model." + keyword + k.split(keyword, 1)[1]
    return k 

print("[1/3] Loading base model configuration and structure...")
processor = Qwen2_5_VLProcessor.from_pretrained(base_model_path, trust_remote_code=True)
model = Qwen2_5_VLForConditionalGeneration.from_pretrained(
    base_model_path, 
    torch_dtype=torch.bfloat16, 
    device_map="cpu", 
    trust_remote_code=True
)

print("[2/3] Loading and remapping SFT state_dict...")
# Load the raw weights from the bin file
state_dict = torch.load(sft_bin_path, map_location="cpu")
new_state_dict = {_remap_key(k): v for k, v in state_dict.items()}

missing, unexpected = model.load_state_dict(new_state_dict, strict=False)
print(f"Missing: {len(missing)}, Unexpected: {len(unexpected)}")

print(f"[3/3] Saving as standard Hugging Face format to: {save_path}")
os.makedirs(save_path, exist_ok=True)

# Save both model and processor in the unified target directory
model.save_pretrained(save_path)
processor.save_pretrained(save_path)
print("[Success] Conversion complete. The model is now ready for HF-native inference.")